import SwiftData
import Foundation

@Model
final class Note {
    @Attribute(.unique) var id: UUID
    var title: String
    var body: String
    var createdAt: Date
    var tags: [String]

    @Relationship(deleteRule: .cascade) var attachments: [Attachment]

    init(title: String, detail: String) {
        self.id = UUID()
        self.title = title
        self.body = body
        self.createdAt = .now
        self.tags = []
        self.attachments = []
    }
}

@Model
final class Attachment {
    var filename: String
    var data: Data
    init(filename: String, data: Data) {
        self.filename = filename
        self.data = data
    }
}

import SwiftUI
import SwiftData

@main
struct NotesApp: App {
    var body: some Scene {
        WindowGroup { ContentView() }
            .modelContainer(for: [Note.self, Attachment.self])
    }
}

struct NotesList: View {
    @Query(sort: \Note.createdAt, order: .reverse) private var notes: [Note]
    @Environment(\.modelContext) private var ctx

    var body: some View {
        List {
            ForEach(notes) { note in
                NavigationLink(note.title) { NoteDetail(note: note) }
            }
            .onDelete { indexes in
                for i in indexes { ctx.delete(notes[i]) }
            }
        }
        .toolbar {
            Button("Nova") {
                ctx.insert(Note(title: "Sem titulo", detail: ""))
            }
        }
    }
}

struct SearchNotes: View {
    let query: String
    @Query private var notes: [Note]

    init(query: String) {
        self.query = query
        let predicate = #Predicate<Note> { note in
            note.title.localizedStandardContains(query)
        }
        _notes = Query(filter: predicate, sort: \Note.createdAt, order: .reverse)
    }

    var body: some View {
        List(notes) { Text($0.title) }
    }
}

@Environment(\.modelContext) private var ctx

func addNote() {
    let n = Note(title: "Nova", detail: "")
    ctx.insert(n)
    // auto-save por padrao; para controle manual:
    // try? ctx.save()
}

func fetchByTitle(_ t: String) throws -> [Note] {
    var desc = FetchDescriptor<Note>(
        predicate: #Predicate { $0.title == t },
        sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
    )
    desc.fetchLimit = 50
    return try ctx.fetch(desc)
}

